"""Build final20 from frozen pilot semantics plus ten new sourced records."""
import json, sys
from pathlib import Path
ROOT=Path(__file__).parent
pilot=json.loads((ROOT/'folklore-legacy-pilot10.json').read_text(encoding='utf8'))
positions=[2,0,3,1,2,1,0,3,2,0,1,3,1,2,3,0,3,1,0,2]
new=[
("В японской игре kitsune-ken какой жест побеждает жест лисицы?",["Староста","Ружьё","Чашка сакэ","Черепаха"],"Ружьё","В kitsune-ken ружьё побеждает лисицу, поскольку может её убить; староста, напротив, побеждает ружьё. Это правило конкретной игры, не общее описание всех кицунэ.","https://www.metmuseum.org/art/collection/search/57034"),
("В японской игре kitsune-ken какой персонаж может околдовать старосту?",["Ружьё","Каппа","Тэнгу","Лисица"],"Лисица","В kitsune-ken староста сильнее ружья, ружьё сильнее лисицы, но лисица может околдовать старосту. Каппа — иной персонаж японского фольклора, не правило этой игры.","https://www.metmuseum.org/art/collection/search/57034"),
("В версии Aladdin из оцифрованного текста LOC чей раб называет себя джинн кольца?",["Лампы","Кольца на пальце","Корабля Синдбада","Платка Ивана"],"Кольца на пальце","Текст LOC различает двух джиннов: первый называет себя рабом кольца на пальце Аладдина, второй — рабом лампы. Лампа поэтому правдоподобна, но отвечает за другого джинна.","https://tile.loc.gov/storage-services/service/rbc/rbc0001/2003/2003juv28132/2003juv28132.pdf"),
("В том же тексте LOC чьим рабом называет себя джинн, явившийся матери Аладдина?",["Кольца","Пещеры","Лампы","Золотого горшка"],"Лампы","В оцифрованном тексте мать видит джинна лампы, тогда как Аладдин ранее видел джинна кольца. Вопрос намеренно фиксирует эту версию текста, не смешивая два волшебных предмета.","https://tile.loc.gov/storage-services/service/rbc/rbc0001/2003/2003juv28132/2003juv28132.pdf"),
("Какие птицы топят лодку Синдбада в пересказе LOC о пятом путешествии?",["Фениксы","Вороны","Жар-птицы","Птицы рок"],"Птицы рок","Библиотека Конгресса сообщает, что в пятом путешествии лодку Синдбада топят птицы рок. Жар-птица — близкий по образу, но иной персонаж русской сказочной традиции.","https://blogs.loc.gov/international-collections/2017/08/the-seven-voyages-of-sindbad-the-sailor/"),
("Как называется бедный носильщик, встречающий богатого морехода в начале рассказа LOC о Синдбаде?",["Синдбад-носильщик","Аладдин","Ананси","Синдбад-мореход"],"Синдбад-носильщик","В пересказе LOC в Багдаде бедный Синдбад-носильщик останавливается у дома богатого Синдбада-морехода. Второй Синдбад тоже существует в этой истории, но он хозяин дома и рассказчик путешествий.","https://blogs.loc.gov/international-collections/2017/08/the-seven-voyages-of-sindbad-the-sailor/"),
("Какой страной LOC связывает Ананси в выставочном описании фольклорной литературы?",["Гана","Япония","Ирландия","Россия"],"Гана","LOC называет паука Ананси популярной фигурой ганской фольклорной литературы. Япония уместна для тэнгу и каппы, но не для этой конкретной привязки Ананси.","https://www.loc.gov/exhibits/world/earth.html"),
("Какую роль Anansi прямо называет путеводитель American Folklife Center?",["Водный демон","Животный трикстер африканской и афродиаспорной традиции","Джинн лампы","Горный дух"],"Животный трикстер африканской и афродиаспорной традиции","Путеводитель LOC относит Anansi к животным трикстерам африканской и афродиаспорной традиции. Джинн лампы — персонаж текста об Аладдине, поэтому это содержательно близкая, но неверная сверхъестественная альтернатива.","https://guides.loc.gov/folktales-oral-storytelling/animal-trickster-tales"),
("Кто, согласно средневековому преданию об единороге, мог его укротить?",["Дева","Рыцарь","Охотник","Дракон"],"Дева","Средневековый бестиарий сообщает, что единорога могла укротить дева. Рыцарь и охотник естественно связаны с охотой на сказочное животное, но источник называет именно деву.","https://www.metmuseum.org/exhibitions/listings/2013/search-for-the-unicorn"),
("Какое существо в средневековом бестиарии названо единственным врагом пантеры?",["Лев","Дракон","Единорог","Грифон"],"Дракон","В средневековом бестиарии единственным врагом пантеры назван дракон. Единорог тоже известен в европейских бестиариях, но в этом противопоставлении он не фигурирует.","https://resources.metmuseum.org/resources/metpublications/pdf/A_Medieval_Bestiary_The_Metropolitan_Museum_of_Art_Bulletin_v_44_no_1_Summer_1986.pdf")]
qs=[]
for i,q in enumerate(pilot['questions']):
  q=q.copy(); correct=q['options'][q['correct_answer']]; others=[x for x in q['options'] if x!=correct]; p=positions[i]; q['options']=others[:p]+[correct]+others[p:]; q['correct_answer']=p; qs.append(q)
revisions={
0:("Сколько вёдер воды выпивает Кощей в сказке «Смерть Кощея Бессмертного», прежде чем разорвать цепи?",["Одно","Два","Три","Семь"],"Три","В опубликованном пересказе Кощей просит воды и после третьего ведра возвращает силу, разрывая двенадцать цепей. Семь — частое сказочное число, но в этом тексте оно не названо."),
1:("За кем Иван присматривает три дня у Бабы-яги в сказке «Смерть Кощея Бессмертного»?",["За воронами","За кобылами Бабы-яги","За огненной птицей","За водяными духами"],"За кобылами Бабы-яги","Баба-яга требует три дня стеречь своих кобылиц и обещает за это богатырского коня. Ворон помогает Ивану в другом эпизоде, но не является предметом этой службы."),
2:("Как называется птицеподобная форма тэнгу с сильным острым клювом в японских представлениях?",["Ко но ха тэнгу","Карасу тэнгу","Каппа","Кицунэ"],"Карасу тэнгу","Карасу тэнгу описывается с птицеподобной головой и острым клювом. Ко но ха тэнгу — близкая форма, но имеет человеческое лицо и огромный длинный нос."),
3:("Какой признак отличает ко но ха тэнгу от карасу тэнгу в японских представлениях?",["Черепаший панцирь","Огромный длинный нос на человеческом лице","Клюв птицы","Горшок золота"],"Огромный длинный нос на человеческом лице","Ко но ха тэнгу представлен с человеческим лицом и огромным длинным носом. Острый клюв относится к карасу тэнгу, а черепаший панцирь — к каппе в другой традиции."),
4:("На чём стоит избушка Бабы-яги в сказочном образе?",["На санях","На камнях","На птичьих ногах","На корнях дуба"],"На птичьих ногах","В библиотечном материале о фольклорном мотиве Баба-яга связана с избушкой на птичьих ногах. Сани и корни создают лесной образ, но не называют отличительный признак её жилища."),
5:("Как называются домашние духи в локальных традициях Кадьякского архипелага, упомянутые рядом с русалками?",["Банши","Суседки","Тэнгу","Ананси"],"Суседки","Источник о локальных традициях Кадьякского архипелага различает водяных русалок и домашних суседок. Банши и тэнгу тоже фольклорные существа, но принадлежат ирландскому и японскому контекстам, а не этому названию."),
6:("Что делает вежливый каппа, из-за чего теряет силу в одном японском рассказе?",["Кланяется в ответ","Пьёт три ведра воды","Надевает красную шапку","Прыгает через огненную реку"],"Кланяется в ответ","В конкретном рассказе вежливый каппа кланяется в ответ, теряет жидкость из углубления на голове и вместе с нею силу. Три ведра воды относятся к Кощею в иной сказке."),
7:("Какая форма тела приписана каппе в одном японском описании?",["Черепашье тело, лягушачьи ноги, обезьянья голова","Лошадиное тело и крылья","Человеческое лицо и длинный нос","Змеиное тело и рога"],"Черепашье тело, лягушачьи ноги, обезьянья голова","В описании каппы соединены черепашье тело, лягушачьи ноги и обезьянья голова. Человеческое лицо с длинным носом — характеристика ко но ха тэнгу, а не каппы."),
8:("Как называют водяных духов в локальных традициях, связанных с северо-восточной Россией?",["Русалки","Тэнгу","Кощей","Ананси"],"Русалки","Справочный материал сообщает о водяных русалках и домашних суседках в локальных традициях, происходящих из северо-восточной России. Тэнгу — японский горный дух, поэтому не подходит к этой региональной привязке."),
9:("Какой предмет Марья Моревна передаёт Ивану для перехода огненной реки?",["Платок","Золотую лампу","Серебряную ложку","Зеркало"],"Платок","Марья Моревна передаёт Ивану платок Кощея; три взмаха вправо создают мост через огненную реку. Серебряная ложка остаётся у родственника Ивана как знак памяти, а не средство переправы.")}
for i,(text,options,answer,explanation) in revisions.items():
  p=positions[i]; others=[x for x in options if x!=answer]; qs[i].update(text=text,options=others[:p]+[answer]+others[p:],correct_answer=p,explanation=explanation)
for j,(text,options,answer,explanation,url) in enumerate(new,11):
  p=positions[j-1]; others=[x for x in options if x!=answer]; qs.append({'id':f'prep-folklore-{j:03d}','type':'choice','text':text,'options':others[:p]+[answer]+others[p:],'correct_answer':p,'explanation':explanation})
pack={'id':'prep-folklore','category':'Мифология/Фольклор','title':'Фольклор — герои и предания','description':pilot['description'],'questions':qs}
outputs={'folklore-legacy20.json':json.dumps(pack,ensure_ascii=False,indent=2)+'\n',
 'folklore-candidate20.md':'# Фольклор — candidate 20\n\n'+''.join(f"## {q['id']}\n\n{q['text']}\n\n"+''.join(f"{chr(65+k)}. {v}\n" for k,v in enumerate(q['options']))+'\n' for q in qs),
 'folklore-editorial-key20.md':'# Фольклор — private key 20\n\n'+''.join(f"## {q['id']}\n\n**Ответ:** {q['options'][q['correct_answer']]}\n\n**Объяснение:** {q['explanation']}\n\n" for q in qs),
 'folklore-source-ledger20.md':(ROOT/'folklore-source-ledger-pilot10.md').read_text(encoding='utf8')+'\n## Final20 additions and revisions\n\n- 2026-10-03 — Met kitsune-ken: https://www.metmuseum.org/art/collection/search/57034\n- 2026-10-03 — LOC Aladdin: https://tile.loc.gov/storage-services/service/rbc/rbc0001/2003/2003juv28132/2003juv28132.pdf\n- 2026-10-03 — LOC Sindbad: https://blogs.loc.gov/international-collections/2017/08/the-seven-voyages-of-sindbad-the-sailor/\n- 2026-10-03 — LOC Anansi: https://www.loc.gov/exhibits/world/earth.html\n- 2026-10-03 — LOC tricksters: https://guides.loc.gov/folktales-oral-storytelling/animal-trickster-tales\n- 2026-10-03 — LOC Baba Yaga: https://blogs.loc.gov/music/files/2023/05/2223-Orpheus-Chamber-Orchestra-Chad-Hoopes-May4-program.pdf?loclr=blogmus\n- 2026-10-03 — LOC house/water spirits: https://guides.loc.gov/meetings-of-frontiers-conference/black\n- 2026-10-03 — Met unicorn: https://www.metmuseum.org/exhibitions/listings/2013/search-for-the-unicorn\n- 2026-10-03 — Met medieval bestiary: https://resources.metmuseum.org/resources/metpublications/pdf/A_Medieval_Bestiary_The_Metropolitan_Museum_of_Art_Bulletin_v_44_no_1_Summer_1986.pdf\n'}
if sys.argv[1:]==['--check']:
  assert all((ROOT/name).is_file() and (ROOT/name).read_text(encoding='utf8')==text for name,text in outputs.items()); print('PASS folklore final20 readonly check')
else:
  for name,text in outputs.items(): (ROOT/name).write_text(text,encoding='utf8')
  print('PASS built folklore final20')
